pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: residual space remaining
    let mut score = post_residual as f64;

    // Large residual penalty (dead space)
    if post_residual > 50 {
        score += 120.0;
    } else if post_residual > 30 {
        score += 70.0;
    }

    // Next item too big for remaining space
    if next_item_size > 0 && post_residual < next_item_size {
        score += 200.0;
    }

    // Mean residual deviation
    let mean_diff = post_residual as f64 - mean_residual;
    if mean_diff > 0.0 {
        score += mean_diff * 0.6;
    } else {
        score += mean_diff * 0.3;
    }

    // Residual-to-capacity ratio
    let ratio = post_residual as f64 / bin_capacity as f64;
    score += ratio * 4.0;

    // Small residual bonus (tight fit)
    if post_residual <= 5 && post_residual > 0 {
        score -= 800.0;
    }

    // Exact fit penalty (empty bin)
    if post_residual == 0 {
        score -= 2500.0;
    }

    // Progress‑weighted residual
    let progress = step_index as f64 / total_items as f64;
    let time_weight = 1.0 - progress;
    score += time_weight * (post_residual as f64 * 0.04);

    // Penalize many open bins
    score -= (open_bins_count as f64) * 0.15;

    // One perfect‑fit bin bonus
    if fitting_bins_count == 1 && bin_residual == item_size {
        score -= 12.0;
    }

    // Lookahead: if next item would fit much better here
    if next_item_size > 0 && post_residual > 0 {
        let ratio_next = next_item_size as f64 / (post_residual as f64 + 1.0);
        if ratio_next > 1.5 {
            score += 50.0;
        }
    }

    // Quadratic residual penalty (fine‑tuning)
    score += (post_residual as f64).powi(2) * 0.001;

    // Log residual adjustment (for very small residuals)
    if post_residual > 0 {
        score += (post_residual as f64).ln() * 2.0;
    }

    score
}

