    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start from the residual after placing the item
    let mut score = post_residual as f64;

    // ---------- Perfect fit ----------
    if post_residual == 0 {
        score -= 2_800.0;
    }

    // ---------- Residual ratio ----------
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    if res_ratio < 0.02 {
        score += 250.0; // almost full but not perfect
    } else if res_ratio < 0.07 {
        score += 120.0; // tight
    } else if res_ratio > 0.92 {
        score -= 250.0; // too full, wasteful
    }

    // ---------- Mean‑residual proximity ----------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.35;

    // ---------- Residual variance penalty ----------
    let variance_penalty = ((post_residual as f64 - mean_residual).powi(2)) * 0.012;
    score += variance_penalty;

    // ---------- Open bins count ----------
    score += (open_bins_count as f64).powi(2) * 0.015;

    // ---------- Fitting bins handling ----------
    if fitting_bins_count == 1 {
        score -= 280.0;
    } else if fitting_bins_count > 8 {
        score += 70.0;
    }

    // ---------- Next‑item lookahead ----------
    if next_item_size > 0 {
        // If current bin cannot fit next item, penalise heavily
        if post_residual < next_item_size {
            score += 220.0;
            // Larger next item gets an extra penalty
            if next_item_size > item_size {
                score += 90.0;
            }
        } else {
            // Reward a margin that can accommodate next item
            let margin = post_residual - next_item_size;
            score -= (margin as f64) * 0.06;
        }
    }

    // ---------- End‑of‑stream ----------
    if step_index > (total_items * 9 / 10) {
        score -= 120.0;
    }

    // ---------- Large item in a big bin ----------
    if item_size > bin_capacity / 2 && post_residual < 6 {
        score -= 90.0;
    }

    // ---------- New bin special handling ----------
    if bin_residual == bin_capacity {
        let new_residual = bin_capacity - item_size;
        let mut new_score = new_residual as f64;
        if new_residual == 0 {
            new_score -= 2_800.0;
        }
        // Penalise opening new bin if many bins already exist
        if open_bins_count > ((total_items as f64) / 15.0) as usize {
            new_score += 350.0;
        }
        // Prefer new bin only if it yields a better score
        if new_score < score {
            score = new_score;
        }
    }

    score
}

